const input = $input.first();
const body = input?.json?.body || input?.json || {};
const sale = body.sale || {};
const errors = [];

function clean(value, max = 1000) {
  const text = String(value ?? '').trim();
  return text ? text.slice(0, max) : '';
}

function isEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(value || '').trim());
}

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function signatureHtml() {
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="font-family:Arial,Helvetica,sans-serif;color:#111111;margin-top:24px;"><tbody><tr><td style="padding:0;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;width:100%;"><tbody><tr><td style="padding:16px 0;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%"><tbody><tr><td valign="top" style="width:140px;padding-right:16px;"><img src="https://cdn.shopify.com/s/files/1/0534/7819/5350/files/fabienne123.jpg?v=1764000653" alt="Fabienne Trapp" width="120" height="120" style="display:block;width:120px;height:120px;border-radius:60px;border:2px solid #111111;object-fit:cover;"></td><td valign="top" style="padding-top:2px;"><div style="font-size:16px;font-weight:700;color:#111111;margin:0 0 4px 0;">Fabienne Trapp</div><div style="font-size:12px;color:#6b7280;margin:0 0 10px 0;">Beratung &amp; Realisierung</div><div style="font-size:13px;font-weight:700;color:#111111;margin:0 0 8px 0;">NEONTRIP</div><div style="font-size:13px;line-height:1.6;color:#111111;">Tel: <a href="tel:+4921154257240" style="color:#111111;text-decoration:none;">+49 211 54257240</a><br>E-Mail: <a href="mailto:support@neontrip.de" style="color:#111111;text-decoration:none;">support@neontrip.de</a><br>Web: <a href="https://www.neontrip.de" style="color:#111111;text-decoration:none;">www.neontrip.de</a><br>Adresse: Bilker Allee 29, 40219 Duesseldorf</div></td></tr></tbody></table></td></tr><tr><td style="padding:0;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background-color:#121212;border-radius:10px;"><tbody><tr><td align="center" style="padding:18px 16px;"><img src="https://cdn.shopify.com/s/files/1/0534/7819/5350/files/weiss_logo_NEONTRIP.png?v=1764003450" alt="NEONTRIP" width="420" style="display:block;width:100%;max-width:420px;height:auto;border:0;outline:none;text-decoration:none;"><div style="margin-top:8px;font-size:11px;font-weight:700;letter-spacing:0.6px;color:#ffffff;">UNIQUE LIGHTING AND BRANDING</div></td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table>`;
}

const recipientEmail = clean(body.recipientEmail, 260).toLowerCase();
const paymentLink = clean(body.paymentLink, 1000);
const reminderKey = clean(body.reminderKey, 260);
const saleId = clean(sale.id, 120);
const customerName = clean(sale.customerName || sale.customerCompany, 180);
const orderRef = clean(sale.shopifyOrderName || sale.offerNumber || sale.saleKey, 180);
const operatorMessage = clean(body.message, 2000);

if (!saleId) errors.push('sale.id missing');
if (!isEmail(recipientEmail)) errors.push('recipientEmail invalid');
if (!paymentLink) errors.push('paymentLink missing');
if (!reminderKey) errors.push('reminderKey missing');
if (recipientEmail.endsWith('@neontrip.test')) errors.push('test recipient blocked');

if (errors.length) {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      error: errors.join('; '),
      saleId: saleId || null,
      reminderKey: reminderKey || null
    }
  }];
}

const subject = `Zahlungserinnerung zu Ihrer NEONTRIP Bestellung${orderRef ? ` ${orderRef}` : ''}`;
const greeting = customerName ? `Hallo ${escapeHtml(customerName)},` : 'Hallo,';
const customMessage = operatorMessage ? `<p style="margin:0 0 16px 0;">${escapeHtml(operatorMessage).replace(/\n/g, '<br>')}</p>` : '';
const bodyHtml = `<div style="font-family:Arial,Helvetica,sans-serif;color:#111111;font-size:15px;line-height:1.55;max-width:620px;"><p style="margin:0 0 16px 0;">${greeting}</p><p style="margin:0 0 16px 0;">zu Ihrer NEONTRIP Bestellung ist die Zahlung noch offen. Sie koennen die Zahlung direkt ueber den folgenden sicheren Shopify-Link abschliessen:</p><p style="margin:22px 0;"><a href="${escapeHtml(paymentLink)}" style="display:inline-block;background:#111111;color:#ffffff;text-decoration:none;font-weight:700;padding:12px 18px;border-radius:6px;">Jetzt bezahlen</a></p><p style="margin:0 0 16px 0;"><a href="${escapeHtml(paymentLink)}" style="color:#111111;word-break:break-all;">${escapeHtml(paymentLink)}</a></p>${customMessage}<p style="margin:0 0 16px 0;">Wenn Sie bereits bezahlt haben, koennen Sie diese Nachricht ignorieren.</p><p style="margin:0;">Viele Gruesse<br>Fabienne von NEONTRIP</p></div>${signatureHtml()}`;

return [{
  json: {
    valid: true,
    saleId,
    reminderKey,
    recipientEmail,
    subject,
    bodyHtml
  }
}];
